Here is the root cause:
The bug was caused by the use of `unregister_netdev` during the shutdown flow, which led to accessing freed resources and calling the netdev's ndo methods after the device had been unregistered. This resulted in crashes due to dereferencing invalid pointers and attempting to perform operations on a network device that was no longer valid.

Here is the patch:

-static void mlx4_en_shutdown(struct net_device *dev)
-{
-	rtnl_lock();
-	netif_device_detach(dev);
-	mlx4_en_close(dev);
-	rtnl_unlock();
-}

 static int mlx4_en_copy_priv(struct mlx4_en_priv *dst,

 void mlx4_en_destroy_netdev(struct net_device *dev)
 {
 	struct mlx4_en_priv *priv = netdev_priv(dev);
 	struct mlx4_en_dev *mdev = priv->mdev;
-	bool shutdown = mdev->dev->persist->interface_state &
-					    MLX4_INTERFACE_STATE_SHUTDOWN;

 	en_dbg(DRV, priv, "Destroying netdev on port:%d\n", priv->port);

 	/* Unregister device - this will close the port if it was up */
 	if (priv->registered) {
 		devlink_port_type_clear(mlx4_get_devlink_port(mdev->dev,
 							      priv->port));
-		if (shutdown)
-			mlx4_en_shutdown(dev);
-		else
-			unregister_netdev(dev);
+		unregister_netdev(dev);
 	}

 	if (priv->allocated)
 		mlx4_free_hwq_res(mdev->dev, &priv->res, MLX4_EN_PAGE_SIZE);

 	cancel_delayed_work(&priv->stats_task);
 	cancel_delayed_work(&priv->service_task);
 	/* flush any pending task for this netdev */
 	flush_workqueue(mdev->workqueue);

 	if (mdev->dev->caps.flags2 & MLX4_DEV_CAP_FLAG2_TS)
 		mlx4_en_remove_timestamp(mdev);

 	/* Detach the netdev so tasks would not attempt to access it */
 	mutex_lock(&mdev->state_lock);
 	mdev->pndev[priv->port] = NULL;
 	mdev->upper[priv->port] = NULL;

 #ifdef CONFIG_RFS_ACCEL
 	mlx4_en_cleanup_filters(priv);
 #endif

 	mlx4_en_free_resources(priv);
 	mutex_unlock(&mdev->state_lock);

 	kfree(priv->tx_ring);
 	kfree(priv->tx_cq);

-	if (!shutdown)
-		free_netdev(dev);
+	free_netdev(dev);
 }



